/**
 * Unit tests for the UserWebauthnCredentialAuthenticatorAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserWebauthnCredentialAuthenticatorAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAuthenticator returns null on a freshly created holder.
     */
    public function testAuthenticatorNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserWebauthnCredentialAuthenticatorAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAuthenticatorAssigned());
        $this->assertNull($holder->getAuthenticator());
    }
}
